</div></div></div></main></form><script>
const rolSelect=document.getElementById('rol'),checks=[...document.querySelectorAll('.permiso-modulo')];let adminAnterior=rolSelect.value==='administrador';function actualizarRolAdmin(){const admin=rolSelect.value==='administrador';if(adminAnterior&&!admin)checks.forEach(c=>c.checked=false);checks.forEach(c=>{const soloAdmin=c.dataset.adminOnly==='1';if(admin)c.checked=true;if(soloAdmin&&!admin)c.checked=false;c.disabled=admin||soloAdmin;});document.getElementById('marcarTodos').disabled=admin;document.getElementById('desmarcarTodos').disabled=admin;adminAnterior=admin;}rolSelect.addEventListener('change',actualizarRolAdmin);actualizarRolAdmin();document.getElementById('marcarTodos').addEventListener('click',()=>checks.forEach(c=>{if(c.dataset.adminOnly!=='1')c.checked=true;}));document.getElementById('desmarcarTodos').addEventListener('click',()=>checks.forEach(c=>{if(c.dataset.adminOnly!=='1')c.checked=false;}));
</script><script>document.body.style.overflow="hidden";$(document).ready(function(){function ocultarLoader(){$(".ui-loader").fadeOut(function(){$(".ui-loader-bg").fadeOut().addClass("sale");document.body.style.overflow="auto";});}setTimeout(ocultarLoader,250);window.addEventListener('pageshow',function(e){if(e.persisted)ocultarLoader();});});</script></body></html>
